import{renderCustomModel,renderDiagram}from './visual.js?v=20261023-physicscomplete01';import{endoFigure}from './endo-figures.js?v=20261023-physicscomplete01';import{buildEndo}from './endo-meshes.js?v=20261023-physicscomplete01';
export function showEndo(spec='insulin',w={}){let[k,s]=spec.split(':'),kind=k,state=k==='temperature'?(s==='2'?'cold':'hot'):s||'normal',o={kind,state,progress:.5,...w},title=w.title||({temperature:'Temperature responses',glands:'Locate the endocrine glands',hormone:'Hormone transport',insulin:'Insulin, glucose and storage',glucagon:'Liver glucose release',data:'Read glucose concentration',diabetes:'Compare the mechanisms',risk:'Evaluate the supplied evidence',feedback:'Opposing control pathways'})[kind]||'Trace the control pathway',figure=endoFigure(o);if(!['temperature','insulin','glucagon'].includes(kind)||w.concealed){renderDiagram(title,w.label||'Original illustrative model or data',figure,'CONTROL AND EVIDENCE');return;}renderCustomModel({name:title,formula:w.label||(kind==='temperature'?'Skin vessels · sweat gland · skeletal muscle':'Hormone signal · glucose units · glycogen store'),kicker:'CONTROL MECHANISM',aria:title+'. Schematic enlarged structures; labelled diagram available.',atoms:[],bonds:[],radius:2.1,viewKey:'endo-'+kind,startPaused:true,note:kind==='temperature'?'Schematic skin section · vessels change diameter in place':'Symbolic units, timing and geometry · not clinical prediction',diagram:figure,build:(g,T)=>buildEndo(g,T,o)});}
